theory = (
 H("A", "A chief executive’s speech", "Bài phát biểu của tổng giám đốc")
 + P("The head of a company talks to staff about a busy year.", "Người đứng đầu công ty nói với nhân viên về một năm nhiều biến động.")
 + T([
    ("<b>capitalise on</b>", "They used the publicity from launching new product lines to do well.", "Họ tận dụng sự chú ý từ việc ra mắt dòng sản phẩm mới."),
    ("<b>come out</b> / <b>succeed in</b>", "The company ended the year stronger, and managed to reverse last year’s fall.", "Công ty kết thúc năm mạnh hơn và đã đảo ngược đà đi xuống năm trước."),
    ("<b>win back</b> / <b>lose out to</b>", "Customers returned from rivals; before that the firm had been less successful than international competitors.", "Khách hàng quay lại từ đối thủ; trước đó công ty kém hơn các đối thủ quốc tế."),
    ("<b>pride yourself on</b>", "They are proud of offering better products at lower prices.", "Họ tự hào cung cấp sản phẩm tốt hơn với giá thấp hơn."),
    ("<b>win through</b> / <b>fall through</b>", "They fought a hostile takeover bid and succeeded; the bid failed to happen.", "Họ chống lại vụ thâu tóm thù địch và đã thắng; vụ thâu tóm đổ bể."),
 ])
 + H("B", "Two students talk about exams", "Hai sinh viên nói chuyện về kỳ thi")
 + T([
    ("<b>get through</b>", "Harry fears he will not pass the end-of-term exam.", "Harry sợ không qua được kỳ thi cuối kỳ."),
    ("<b>sail through</b>", "He wishes he could pass exams easily like some people (see Unit 5).", "Anh ước mình qua kỳ thi dễ dàng như vài người (xem bài 5)."),
    ("<b>pack in</b>", "(informal) …and still manage to do lots of activities in their free time.", "(thân mật) …mà vẫn làm được rất nhiều việc lúc rảnh."),
    ("<b>carry off</b>", "Libby says he did a difficult presentation quite well.", "Libby nói anh đã làm bài thuyết trình khó khá tốt."),
    ("<b>get by</b>", "(informal) He knew just enough to manage, thanks to things he found online the night before (see Unit 1).", "(thân mật) Anh chỉ vừa đủ để xoay xở nhờ tài liệu tìm trên mạng tối hôm trước (xem bài 1)."),
 ])
 + H("C", "Other verbs connected with succeeding and failing", "Các động từ khác về thành công và thất bại")
 + T([
    ("<b>win out</b>", "(informal) a feeling, here curiosity, is stronger than others (going to a lecture on bees)", "(thân mật) một cảm xúc, ở đây là tò mò, thắng thế (đi nghe bài giảng về ong)"),
    ("<b>doom</b> … <b>to</b>", "make a plan certain to fail (lack of enthusiasm)", "khiến kế hoạch chắc chắn thất bại (thiếu nhiệt tình)"),
    ("<b>pull through</b>", "get through, or help someone get through, a hard time (support from friends and family)", "vượt qua, hoặc giúp ai vượt qua, giai đoạn khó khăn (nhờ bạn bè, gia đình)"),
    ("<b>rise above</b>", "not let something bad, such as negative criticism, upset you", "không để điều xấu, như lời chê bai, ảnh hưởng mình"),
    ("<b>fall behind</b>", "score fewer points than another team (three points behind Liverpool)", "kém điểm đội khác (kém Liverpool ba điểm)"),
 ])
 + NOTE("<b>Exercise 27.4 – ten particle errors</b>: lose <b>out</b> to (not off), succeed <b>in</b> + -ing (not succeed to), sail <b>through</b> (not over), fall <b>behind</b> (not back), pride yourself <b>on</b> (not for), pull yourself <b>through</b> (not across), carry it <b>off</b> (not out), pack <b>in</b> (not up), get <b>through</b> exams (not get by), only just got <b>by/through</b> (not over).",
        "<b>Bài 27.4 – mười lỗi tiểu từ</b>: lose <b>out</b> to (không phải off), succeed <b>in</b> + -ing (không phải succeed to), sail <b>through</b> (không phải over), fall <b>behind</b> (không phải back), pride yourself <b>on</b> (không phải for), pull yourself <b>through</b> (không phải across), carry it <b>off</b> (không phải out), pack <b>in</b> (không phải up), get <b>through</b> kỳ thi (không phải get by), only just got <b>by/through</b> (không phải over).")
)
